  const customers = [
    { id: 'C-001', name: 'Alice', email: 'a@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Bob', email: 'b@example.com', tier: 'standard' },
  ];
  const invoices = [
    { number: 'INV-001', customerId: 'C-001' },
    { number: 'INV-002', customerId: 'C-001' },
    { number: 'INV-003', customerId: 'C-002' },
  ];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  const aliceInvoices = result.value.invoices.filter((inv) => inv.number.startsWith('INV-00'));
  assert.equal(aliceInvoices[0].customerId, 'C-002');
  assert.equal(aliceInvoices[1].customerId, 'C-002');
  assert.equal(aliceInvoices[2].customerId, 'C-002');
});

