    { id: 'C-001', name: 'Alice', email: 'a@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Bob', email: 'b@example.com', tier: 'standard' },
  ];
  const result = mergeCustomers(customers, [], 'c-001', 'C-002');

  assert.equal(result.ok, true);
  const ids = result.value.customers.map((c) => c.id);
  assert.ok(!ids.includes('C-001'));
});

